22: // Dialer contains options for func (*Dialer) Dial.
23: type Dialer struct {
24: 	MaxCreditBalance uint16 // if it's zero, clientMaxCreditBalance is used. (See feature.go for more details)
25: 	Negotiator       Negotiator
26: 	Initiator        Initiator
27: }
28: 
29: // Dial performs negotiation and authentication.
30: // It returns a session. It doesn't support NetBIOS transport.
31: // This implementation doesn't support multi-session on the same TCP connection.
32: // If you want to use another session, you need to prepare another TCP connection at first.
33: func (d *Dialer) Dial(tcpConn net.Conn) (*Session, error) {
34: 	return d.DialContext(context.Background(), tcpConn)
35: }
36: 
37: // DialContext performs negotiation and authentication using the provided context.
38: // Note that returned session doesn't inherit context.
39: // If you want to use the same context, call Session.WithContext manually.
40: // This implementation doesn't support multi-session on the same TCP connection.
41: // If you want to use another session, you need to prepare another TCP connection at first.
42: func (d *Dialer) DialContext(ctx context.Context, tcpConn net.Conn) (*Session, error) {
43: 	if ctx == nil {
44: 		panic("nil context")
45: 	}
46: 	if d.Initiator == nil {
47: 		return nil, &InternalError{"Initiator is empty"}
48: 	}
49: 	if i, ok := d.Initiator.(*NTLMInitiator); ok {
50: 		if i.User == "" {
51: 			return nil, &InternalError{"Anonymous account is not supported yet. Use guest account instead"}
52: 		}
53: 	}
54: 
55: 	maxCreditBalance := d.MaxCreditBalance
56: 	if maxCreditBalance == 0 {
57: 		maxCreditBalance = clientMaxCreditBalance
58: 	}
59: 
60: 	a := openAccount(maxCreditBalance)
61: 
62: 	conn, err := d.Negotiator.negotiate(direct(tcpConn), a, ctx)
63: 	if err != nil {
64: 		return nil, err
65: 	}
66: 
67: 	s, err := sessionSetup(conn, d.Initiator, ctx)
68: 	if err != nil {
69: 		return nil, err
70: 	}
71: 
72: 	return &Session{s: s, ctx: context.Background(), addr: tcpConn.RemoteAddr().String()}, nil
73: }
