94: // Mount mounts the SMB share.
95: // sharename must follow format like `<share>` or `\\<server>\<share>`.
96: // Note that the mounted share doesn't inherit session's context.
97: // If you want to use the same context, call Share.WithContext manually.
98: func (c *Session) Mount(sharename string) (*Share, error) {
99: 	sharename = normPath(sharename)
100: 
101: 	if !strings.ContainsRune(sharename, '\\') {
102: 		sharename = fmt.Sprintf(`\\%s\%s`, c.addr, sharename)
103: 	}
104: 
105: 	if err := validateMountPath(sharename); err != nil {
106: 		return nil, err
107: 	}
108: 
109: 	tc, err := treeConnect(c.s, sharename, 0, c.ctx)
110: 	if err != nil {
111: 		return nil, err
112: 	}
113: 
114: 	return &Share{treeConn: tc, ctx: context.Background()}, nil
115: }
