274: func (fs *Share) OpenFile(name string, flag int, perm os.FileMode) (*File, error) {
275: 	name = normPath(name)
276: 
277: 	if err := validatePath("open", name, false); err != nil {
278: 		return nil, err
279: 	}
280: 
281: 	var access uint32
282: 	switch flag & (os.O_RDONLY | os.O_WRONLY | os.O_RDWR) {
283: 	case os.O_RDONLY:
284: 		access = GENERIC_READ
285: 	case os.O_WRONLY:
286: 		access = GENERIC_WRITE
287: 	case os.O_RDWR:
288: 		access = GENERIC_READ | GENERIC_WRITE
289: 	}
290: 	if flag&os.O_CREATE != 0 {
291: 		access |= GENERIC_WRITE
292: 	}
293: 	if flag&os.O_APPEND != 0 {
294: 		access &^= GENERIC_WRITE
295: 		access |= FILE_APPEND_DATA
296: 	}
297: 
298: 	sharemode := uint32(FILE_SHARE_READ | FILE_SHARE_WRITE)
299: 
300: 	var createmode uint32
301: 	switch {
302: 	case flag&(os.O_CREATE|os.O_EXCL) == (os.O_CREATE | os.O_EXCL):
303: 		createmode = FILE_CREATE
304: 	case flag&(os.O_CREATE|os.O_TRUNC) == (os.O_CREATE | os.O_TRUNC):
305: 		createmode = FILE_OVERWRITE_IF
306: 	case flag&os.O_CREATE == os.O_CREATE:
307: 		createmode = FILE_OPEN_IF
308: 	case flag&os.O_TRUNC == os.O_TRUNC:
309: 		createmode = FILE_OVERWRITE
310: 	default:
311: 		createmode = FILE_OPEN
312: 	}
313: 
314: 	var attrs uint32 = FILE_ATTRIBUTE_NORMAL
315: 	if perm&0200 == 0 {
316: 		attrs = FILE_ATTRIBUTE_READONLY
317: 	}
318: 
319: 	req := &CreateRequest{
320: 		SecurityFlags:        0,
321: 		RequestedOplockLevel: SMB2_OPLOCK_LEVEL_NONE,
322: 		ImpersonationLevel:   Impersonation,
323: 		SmbCreateFlags:       0,
324: 		DesiredAccess:        access,
325: 		FileAttributes:       attrs,
326: 		ShareAccess:          sharemode,
327: 		CreateDisposition:    createmode,
328: 		CreateOptions:        FILE_SYNCHRONOUS_IO_NONALERT,
329: 	}
330: 
331: 	f, err := fs.createFile(name, req, true)
332: 	if err != nil {
333: 		return nil, &os.PathError{Op: "open", Path: name, Err: err}
334: 	}
335: 	if flag&os.O_APPEND != 0 {
336: 		f.seek(0, io.SeekEnd)
337: 	}
338: 	return f, nil
339: }
