372: func (fs *Share) Readlink(name string) (string, error) {
373: 	name = normPath(name)
374: 
375: 	if err := validatePath("readlink", name, false); err != nil {
376: 		return "", err
377: 	}
378: 
379: 	create := &CreateRequest{
380: 		SecurityFlags:        0,
381: 		RequestedOplockLevel: SMB2_OPLOCK_LEVEL_NONE,
382: 		ImpersonationLevel:   Impersonation,
383: 		SmbCreateFlags:       0,
384: 		DesiredAccess:        FILE_READ_ATTRIBUTES,
385: 		FileAttributes:       FILE_ATTRIBUTE_NORMAL,
386: 		ShareAccess:          FILE_SHARE_READ | FILE_SHARE_WRITE,
387: 		CreateDisposition:    FILE_OPEN,
388: 		CreateOptions:        FILE_OPEN_REPARSE_POINT,
389: 	}
390: 
391: 	f, err := fs.createFile(name, create, false)
392: 	if err != nil {
393: 		return "", &os.PathError{Op: "readlink", Path: name, Err: err}
394: 	}
395: 
396: 	req := &IoctlRequest{
397: 		CtlCode:           FSCTL_GET_REPARSE_POINT,
398: 		OutputOffset:      0,
399: 		OutputCount:       0,
400: 		MaxInputResponse:  0,
401: 		MaxOutputResponse: uint32(f.maxTransactSize()),
402: 		Flags:             SMB2_0_IOCTL_IS_FSCTL,
403: 		Input:             nil,
404: 	}
405: 
406: 	output, err := f.ioctl(req)
407: 	if e := f.close(); err == nil {
408: 		err = e
409: 	}
410: 	if err != nil {
411: 		return "", &os.PathError{Op: "readlink", Path: f.name, Err: err}
412: 	}
413: 
414: 	r := SymbolicLinkReparseDataBufferDecoder(output)
415: 	if r.IsInvalid() {
416: 		return "", &os.PathError{Op: "readlink", Path: f.name, Err: &InvalidResponseError{"broken symbolic link response data buffer format"}}
417: 	}
418: 
419: 	target := r.SubstituteName()
420: 
421: 	switch {
422: 	case strings.HasPrefix(target, `\??\UNC\`):
423: 		target = `\\` + target[8:]
424: 	case strings.HasPrefix(target, `\??\`):
425: 		target = target[4:]
426: 	}
427: 
428: 	return target, nil
429: }
