817: func (fs *Share) ReadFile(filename string) ([]byte, error) {
818: 	f, err := fs.Open(filename)
819: 	if err != nil {
820: 		return nil, err
821: 	}
822: 	defer f.Close()
823: 
824: 	size64 := f.fileStat.Size() + 1 // one byte for final read at EOF
825: 
826: 	var size int
827: 
828: 	if size64 <= maxInt {
829: 		size = int(size64)
830: 
831: 		// If a file claims a small size, read at least 512 bytes.
832: 		// In particular, files in Linux's /proc claim size 0 but
833: 		// then do not work right if read in small pieces,
834: 		// so an initial read of 1 byte would not work correctly.
835: 		if size < 512 {
836: 			size = 512
837: 		}
838: 	} else {
839: 		size = maxInt
840: 	}
841: 
842: 	data := make([]byte, 0, size)
843: 	for {
844: 		if len(data) >= cap(data) {
845: 			d := append(data[:cap(data)], 0)
846: 			data = d[:len(data)]
847: 		}
848: 		n, err := f.Read(data[len(data):cap(data)])
849: 		data = data[:len(data)+n]
850: 		if err != nil {
851: 			if err == io.EOF {
852: 				err = nil
853: 			}
854: 			return data, err
855: 		}
856: 	}
857: }
