939: func (fs *Share) createFileRec(name string, req *CreateRequest) (f *File, err error) {
940: 	for i := 0; i < clientMaxSymlinkDepth; i++ {
941: 		req.CreditCharge, _, err = fs.loanCredit(0)
942: 		defer func() {
943: 			if err != nil {
944: 				fs.chargeCredit(req.CreditCharge)
945: 			}
946: 		}()
947: 		if err != nil {
948: 			return nil, err
949: 		}
950: 
951: 		req.Name = name
952: 
953: 		res, err := fs.sendRecv(SMB2_CREATE, req)
954: 		if err != nil {
955: 			if rerr, ok := err.(*ResponseError); ok && NtStatus(rerr.Code) == STATUS_STOPPED_ON_SYMLINK {
956: 				if len(rerr.data) > 0 {
957: 					name, err = evalSymlinkError(req.Name, rerr.data[0])
958: 					if err != nil {
959: 						return nil, err
960: 					}
961: 					continue
962: 				}
963: 			}
964: 			return nil, err
965: 		}
966: 
967: 		r := CreateResponseDecoder(res)
968: 		if r.IsInvalid() {
969: 			return nil, &InvalidResponseError{"broken create response format"}
970: 		}
971: 
972: 		f = fs.newFile(r, name)
973: 
974: 		return f, nil
975: 	}
976: 
977: 	return nil, &InternalError{"Too many levels of symbolic links"}
978: }
