597: func accept(cmd uint16, pkt []byte) (res []byte, err error) {
598: 	p := PacketCodec(pkt)
599: 	if command := p.Command(); cmd != command {
600: 		return nil, &InvalidResponseError{fmt.Sprintf("expected command: %v, got %v", cmd, command)}
601: 	}
602: 
603: 	status := NtStatus(p.Status())
604: 
605: 	switch status {
606: 	case STATUS_SUCCESS:
607: 		return p.Data(), nil
608: 	case STATUS_OBJECT_NAME_COLLISION:
609: 		return nil, os.ErrExist
610: 	case STATUS_OBJECT_NAME_NOT_FOUND, STATUS_OBJECT_PATH_NOT_FOUND:
611: 		return nil, os.ErrNotExist
612: 	case STATUS_ACCESS_DENIED, STATUS_CANNOT_DELETE:
613: 		return nil, os.ErrPermission
614: 	}
615: 
616: 	switch cmd {
617: 	case SMB2_SESSION_SETUP:
618: 		if status == STATUS_MORE_PROCESSING_REQUIRED {
619: 			return p.Data(), nil
620: 		}
621: 	case SMB2_QUERY_INFO:
622: 		if status == STATUS_BUFFER_OVERFLOW {
623: 			return nil, &ResponseError{Code: uint32(status)}
624: 		}
625: 	case SMB2_IOCTL:
626: 		if status == STATUS_BUFFER_OVERFLOW {
627: 			if !IoctlResponseDecoder(p.Data()).IsInvalid() {
628: 				return p.Data(), &ResponseError{Code: uint32(status)}
629: 			}
630: 		}
631: 	case SMB2_READ:
632: 		if status == STATUS_BUFFER_OVERFLOW {
633: 			return nil, &ResponseError{Code: uint32(status)}
634: 		}
635: 	case SMB2_CHANGE_NOTIFY:
636: 		if status == STATUS_NOTIFY_ENUM_DIR {
637: 			return nil, &ResponseError{Code: uint32(status)}
638: 		}
639: 	}
640: 
641: 	return nil, acceptError(uint32(status), p.Data())
642: }
