644: func acceptError(status uint32, res []byte) error {
645: 	r := ErrorResponseDecoder(res)
646: 	if r.IsInvalid() {
647: 		return &InvalidResponseError{"broken error response format"}
648: 	}
649: 
650: 	eData := r.ErrorData()
651: 
652: 	if count := r.ErrorContextCount(); count != 0 {
653: 		data := make([][]byte, count)
654: 		for i := range data {
655: 			ctx := ErrorContextResponseDecoder(eData)
656: 			if ctx.IsInvalid() {
657: 				return &InvalidResponseError{"broken error context response format"}
658: 			}
659: 
660: 			data[i] = ctx.ErrorContextData()
661: 
662: 			next := ctx.Next()
663: 
664: 			if len(eData) < next {
665: 				return &InvalidResponseError{"broken error context response format"}
666: 			}
667: 
668: 			eData = eData[next:]
669: 		}
670: 		return &ResponseError{Code: status, data: data}
671: 	}
672: 	return &ResponseError{Code: status, data: [][]byte{eData}}
