40: // MkdirAll mimics os.MkdirAll
41: func (fs *Share) MkdirAll(path string, perm os.FileMode) error {
42: 	path = normPath(path)
43: 
44: 	// Fast path: if we can tell whether path is a directory or file, stop with success or error.
45: 	dir, err := fs.Stat(path)
46: 	if err == nil {
47: 		if dir.IsDir() {
48: 			return nil
49: 		}
50: 		return &os.PathError{Op: "mkdir", Path: path, Err: syscall.ENOTDIR}
51: 	}
52: 
53: 	// Slow path: make sure parent exists and then call Mkdir for path.
54: 	i := len(path)
55: 	for i > 0 && IsPathSeparator(path[i-1]) { // Skip trailing path separator.
56: 		i--
57: 	}
58: 
59: 	j := i
60: 	for j > 0 && !IsPathSeparator(path[j-1]) { // Scan backward over element.
61: 		j--
62: 	}
63: 
64: 	if j > 1 {
65: 		// Create parent
66: 		err = fs.MkdirAll(path[0:j-1], perm)
67: 		if err != nil {
68: 			return err
69: 		}
70: 	}
71: 
72: 	// Parent now exists; invoke Mkdir and use its result.
73: 	err = fs.Mkdir(path, perm)
74: 	if err != nil {
75: 		// Handle arguments like "foo/." by
76: 		// double-checking that directory doesn't exist.
77: 		dir, err1 := fs.Lstat(path)
78: 		if err1 == nil && dir.IsDir() {
79: 			return nil
80: 		}
81: 		return err
82: 	}
83: 	return nil
84: }
