// Glob should work like filepath.Glob.
func (fs *Share) Glob(pattern string) (matches []string, err error) {
	pattern = normPattern(pattern)

	// Check pattern is well-formed.
	if _, err := Match(pattern, ""); err != nil {
		return nil, err
